#!/usr/bin/env python3
"""Generate the register header and asm tables for the PSE firmware rewrite (poe-fw/, #26) from the hwdb register table.

Usage: poe_fw_genhdr.py [--check]
  Reads hwdb/firmware/bcm59111-regs.tsv; writes poe-fw/inc/bcm59111_regs.h, poe-fw/src/hosttab.s (host write/read
  dispatch tables, 128 x [FF hi lo]) and poe-fw/src/chan_isr.s (4 channel ISRs).
  --check: write nothing, exit 1 when a generated file differs from disk (used by poe_fw_build.py).
  Log: tmp/logs/poe_fw_genhdr.log.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from _cli import help_guard  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
TSV = ROOT / "hwdb/firmware/bcm59111-regs.tsv"
OUT_H = ROOT / "poe-fw/inc/bcm59111_regs.h"
OUT_TAB = ROOT / "poe-fw/src/hosttab.s"
OUT_ISR = ROOT / "poe-fw/src/chan_isr.s"
HOOK_NOTE = "generated by scripts/poe_fw_genhdr.py from hwdb/firmware/bcm59111-regs.tsv: do not edit"

CH_BASE = 0x8078   # struct chan array (chan.h)
CH_STRIDE = 20


def load():
    rows = []
    for ln in TSV.read_text().splitlines():
        if not ln.strip() or ln.startswith("#") or ln.startswith("reg\t"):
            continue
        f = ln.split("\t")
        f += [""] * (10 - len(f))
        rows.append({"reg": int(f[0], 16), "name": f[1], "access": f[2], "wh": f[5], "rh": f[6]})
    assert [r["reg"] for r in rows] == list(range(128)), "regs.tsv must list 0x00..0x7F once"
    return rows


def header(rows):
    o = [f"/* {HOOK_NOTE} */", "#ifndef BCM59111_REGS_H", "#define BCM59111_REGS_H", ""]
    for r in rows:
        o.append(f"#define R_{r['name']:<20} 0x{r['reg']:02X}")
    wh = [r["name"] for r in rows if r["wh"]]
    rh = [r["name"] for r in rows if r["rh"]]
    o += ["", "/* handlers that must exist as wh_<NAME> / rh_<NAME> (link fails otherwise) */",
          "#define WRITE_HANDLERS(X) \\"] + [f"\tX({n}) \\" for n in wh] + ["",
          "#define READ_HANDLERS(X) \\"] + [f"\tX({n}) \\" for n in rh] + ["", "#endif", ""]
    return "\n".join(o)


def tables(rows):
    o = [f"; {HOOK_NOTE}", "\t.module hosttab", "\t.globl _wh_nop", "\t.globl _rh_nop"]
    for r in rows:
        if r["wh"]:
            o.append(f"\t.globl _wh_{r['name']}")
        if r["rh"]:
            o.append(f"\t.globl _rh_{r['name']}")
    for tab, key, nop in (("host_write_table", "wh", "_wh_nop"), ("host_read_table", "rh", "_rh_nop")):
        o += ["", "\t.area CONST (CODE)", f"\t.globl _{tab}", f"_{tab}:"]
        for r in rows:
            fn = f"_{key}_{r['name']}" if r[key] else nop
            o.append(f"\t.db 0xFF, >{fn}, {fn}\t; {r['reg']:02X} {r['name']}")
    return "\n".join(o) + "\n"


def chan_isrs():
    o = [f"; {HOOK_NOTE}", "; stock isr_chan0..3 (names TSV 0x4255 0x40DD 0x42CD 0x4345): A and DPTR only, no bank switch",
         "; event bit -> chan block flag: stock 0x4255..0x42CA (ch0 read in full; ch1..3 follow the same pattern, I)",
         "\t.module chan_isr", "\t.area CSEG (CODE)", f"; struct chan: ev_hi +0, ev_lo +1, stride {CH_STRIDE}"]
    for k in range(4):
        sfr = 0xBC + k
        base = CH_BASE + CH_STRIDE * k
        ip = 0xBA + k
        svc = 0x19 + k
        hi_bit, lo_bit = 2 * k + 1, 2 * k
        o += ["", f"\t.globl _hook_chan{k}", f"_hook_chan{k}:",
              f"\tclr\t0x{ip:02X}\t\t; IP.{2 + k}", f"\tsetb\t0x{svc:02X}\t\t; service flag 0x23.{k + 1}"]

        def ev(label, bit, ack, off, orv):
            return [f"\tmov\ta,0x{sfr:02X}", f"\tjnb\tacc.{bit},{label}", f"\tmov\t0x{sfr:02X},#0x{ack:02X}",
                    f"\tmov\tdptr,#0x{base + off:04X}", "\tmovx\ta,@dptr", f"\torl\ta,#0x{orv:02X}", "\tmovx\t@dptr,a",
                    f"{label}:"]
        n = 10 * k
        o += ev(f"{n + 1}$", 7, 0x80, 0, 0x40)
        o += ev(f"{n + 2}$", 6, 0x40, 1, 0x01)
        o += ev(f"{n + 3}$", 4, 0x10, 1, 0x04)
        o += ev(f"{n + 4}$", 3, 0x08, 0, 0x10)
        o += [f"\tmov\ta,0x{sfr:02X}", f"\tjnb\tacc.1,{n + 5}$", "\tmov\ta,0x95", f"\tjnb\tacc.{hi_bit},{n + 6}$",
              f"\tmov\tdptr,#0x{base:04X}", "\tmovx\ta,@dptr", "\torl\ta,#0x01", "\tmovx\t@dptr,a",
              f"\tmov\t0x95,#0x{1 << hi_bit:02X}", f"{n + 6}$:", "\tmov\ta,0x95", f"\tjnb\tacc.{lo_bit},{n + 5}$",
              f"\tmov\t0x95,#0x{1 << lo_bit:02X}", f"{n + 5}$:"]
        o += ev(f"{n + 7}$", 2, 0x04, 0, 0x08)
        o += ev(f"{n + 8}$", 0, 0x01, 0, 0x80)
        o += [f"\tsetb\t0x{ip:02X}", "\tret"]
    return "\n".join(o) + "\n"


def main():
    help_guard(__doc__)
    check = "--check" in sys.argv[1:]
    rows = load()
    outs = {OUT_H: header(rows), OUT_TAB: tables(rows), OUT_ISR: chan_isrs()}
    bad = []
    log = ROOT / "tmp/logs/poe_fw_genhdr.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    for p, text in outs.items():
        cur = p.read_text() if p.exists() else None
        if check:
            if cur != text:
                bad.append(p)
        else:
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text)
    msg = (f"check: {'STALE ' + ', '.join(str(p.relative_to(ROOT)) for p in bad) if bad else 'up to date'}"
           if check else "wrote " + ", ".join(str(p.relative_to(ROOT)) for p in outs))
    print(msg)
    with log.open("a") as f:
        f.write(msg + "\n")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())
